USE CATALOG dcp_synth;
CREATE OR REPLACE VIEW `03_gold`.dp01_patient_glucose_timeline AS SELECT reading_id,patient_id,event_time,glucose_mmol_l,trend,device_id,source_id,ingested_at,_run_id FROM `02_silver`.glucose_readings WHERE quality_status='PASS';
CREATE OR REPLACE TABLE `03_gold`.dp02_patient_glucose_summary USING DELTA AS SELECT patient_id,CAST(event_time AS DATE) measure_date,ROUND(AVG(glucose_mmol_l),2) mean_glucose_mmol_l,ROUND(percentile_approx(glucose_mmol_l,0.5),2) median_glucose_mmol_l,ROUND(100.0*COUNT_IF(glucose_mmol_l BETWEEN 3.9 AND 10.0)/NULLIF(COUNT(*),0),2) tir_pct,ROUND(100.0*COUNT_IF(glucose_mmol_l<3.9)/NULLIF(COUNT(*),0),2) tbr_pct,ROUND(100.0*COUNT_IF(glucose_mmol_l>10.0)/NULLIF(COUNT(*),0),2) tar_pct,COUNT(*) reading_count,MAX(ingested_at) refreshed_at FROM `02_silver`.glucose_readings WHERE quality_status='PASS' GROUP BY patient_id,CAST(event_time AS DATE);
CREATE OR REPLACE VIEW `03_gold`.dp03_patient_self_management_events AS SELECT entry_id,patient_id,CAST(event_time AS TIMESTAMP) event_time,event_type,CAST(carbohydrates_g AS INT) carbohydrates_g,CAST(insulin_units AS DOUBLE) insulin_units,source_application,source_id,CAST(ingested_at AS TIMESTAMP) ingested_at,_run_id FROM `01_bronze`.mysugr_logbook;
CREATE OR REPLACE VIEW `03_gold`.dp09_patient_device_status AS SELECT event_id,patient_id,device_id,event_time,battery_pct,sync_status,error_code,source_id,ingested_at,_run_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY patient_id,device_id ORDER BY CAST(event_time AS TIMESTAMP) DESC,event_id DESC) rn FROM `01_bronze`.device_events) WHERE rn=1;
